Optimal Solution (Prefix Sum with Hash Map):

Key Concept:
If current prefix sum is `curr_sum` and there was a previous prefix sum `curr_sum - target` at index `j`, then the subarray from index `j + 1` to `i` sums to `target`.

Python Implementation:
```python
def find_subarray_sum(nums: list[int], target: int) -> list[int]:
    prefix_map = {0: -1}  # prefix_sum -> first seen index
    curr_sum = 0

    for i, x in enumerate(nums):
        curr_sum += x
        if (curr_sum - target) in prefix_map:
            return [prefix_map[curr_sum - target] + 1, i]
        if curr_sum not in prefix_map:
            prefix_map[curr_sum] = i

    return [-1, -1]

print(find_subarray_sum([10, 2, -2, -20, 10], -10)) # Output: [0, 3]
print(find_subarray_sum([1, 4, 20, 3, 10, 5], 33))    # Output: [2, 4]
```

C++ Implementation:
```cpp
#include <vector>
#include <unordered_map>
#include <iostream>
using namespace std;

vector<int> subarraySum(const vector<int>& nums, int target) {
    unordered_map<long long, int> prefixMap;
    prefixMap[0] = -1;
    long long currSum = 0;

    for (int i = 0; i < (int)nums.size(); ++i) {
        currSum += nums[i];
        long long complement = currSum - target;
        if (prefixMap.find(complement) != prefixMap.end()) {
            return {prefixMap[complement] + 1, i};
        }
        if (prefixMap.find(currSum) == prefixMap.end()) {
            prefixMap[currSum] = i;
        }
    }
    return {-1, -1};
}
```
Time Complexity: O(N) single pass.
Auxiliary Space: O(N) hash map storage.

Optimal Solution (Remainder Frequency Bucketing):

Key Insight:
`(a + b) % k == 0` implies `(a % k + b % k) % k == 0`.
- If `rem == 0`, pair with another number having `rem == 0`: count = `C(freq[0], 2)`.
- If `rem * 2 == k`, pair with another number having the same remainder: count = `C(freq[rem], 2)`.
- Otherwise, numbers with remainder `r` pair with numbers with remainder `k - r`: count = `freq[r] * freq[k - r]`.

Python Implementation:
```python
def count_divisible_pairs(nums: list[int], k: int) -> int:
    from collections import defaultdict
    freq = defaultdict(int)
    count = 0

    for num in nums:
        rem = num % k
        complement = (k - rem) % k
        count += freq[complement]
        freq[rem] += 1

    return count

print(count_divisible_pairs([1, 2, 3, 4, 5, 6], 5)) # Output: 3
```

C++ Implementation:
```cpp
#include <vector>
#include <iostream>
using namespace std;

long long countDivisiblePairs(const vector<int>& nums, int k) {
    vector<long long> freq(k, 0);
    long long count = 0;
    for (int num : nums) {
        int rem = ((num % k) + k) % k;
        int complement = (k - rem) % k;
        count += freq[complement];
        freq[rem]++;
    }
    return count;
}
```
Time Complexity: O(N)
Auxiliary Space: O(K)

Optimal Solution (Two Pointers Technique):

Approach:
- Use `left` pointer at 0 and `right` pointer at N - 1.
- Track `left_max` and `right_max`.
- If `height[left] < height[right]`: water trapped at `left` depends strictly on `left_max`. If `height[left] >= left_max`, update `left_max`; else add `left_max - height[left]` to water. Advance `left`.
- Otherwise: symmetric logic for `right`. Decrement `right`.

Python Implementation:
```python
def trap_rain_water(height: list[int]) -> int:
    if not height: return 0
    left, right = 0, len(height) - 1
    left_max, right_max = 0, 0
    water = 0

    while left < right:
        if height[left] < height[right]:
            if height[left] >= left_max:
                left_max = height[left]
            else:
                water += left_max - height[left]
            left += 1
        else:
            if height[right] >= right_max:
                right_max = height[right]
            else:
                water += right_max - height[right]
            right -= 1

    return water

print(trap_rain_water([0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1])) # Output: 6
```

C++ Implementation:
```cpp
#include <vector>
#include <algorithm>
#include <iostream>
using namespace std;

int trap(const vector<int>& height) {
    int n = height.size();
    int left = 0, right = n - 1;
    int leftMax = 0, rightMax = 0, water = 0;

    while (left < right) {
        if (height[left] < height[right]) {
            if (height[left] >= leftMax) leftMax = height[left];
            else water += leftMax - height[left];
            left++;
        } else {
            if (height[right] >= rightMax) rightMax = height[right];
            else water += rightMax - height[right];
            right--;
        }
    }
    return water;
}
```
Time Complexity: O(N)
Auxiliary Space: O(1)

Optimal Solution (Transpose Matrix then Reverse Each Row):

Key Mathematical Steps:
1. Transpose the matrix: Swap `matrix[i][j]` with `matrix[j][i]` for all `j > i`.
2. Reverse each row: Flip elements of each row horizontally.

Python Implementation:
```python
def rotate_matrix(matrix: list[list[int]]) -> None:
    n = len(matrix)
    # Step 1: Transpose
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Step 2: Reverse each row
    for row in matrix:
        row.reverse()

mat = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
rotate_matrix(mat)
print(mat) # Output: [[7, 4, 1], [8, 5, 2], [9, 6, 3]]
```

C++ Implementation:
```cpp
#include <vector>
#include <algorithm>
#include <iostream>
using namespace std;

void rotate(vector<vector<int>>& matrix) {
    int n = matrix.size();
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            swap(matrix[i][j], matrix[j][i]);
        }
    }
    for (int i = 0; i < n; ++i) {
        std::reverse(matrix[i].begin(), matrix[i].end());
    }
}
```
Time Complexity: O(N^2)
Auxiliary Space: O(1) in-place

Optimal Solution (Sliding Window with Hash Map Indexing):

Approach:
- Maintain a hash map storing the most recent index where each character was seen.
- Expand window right pointer `r`. If character `s[r]` was seen at index `j >= l`, jump `l` directly to `j + 1`.
- Update `max_len = max(max_len, r - l + 1)`.

Python Implementation:
```python
def length_of_longest_substring(s: str) -> int:
    char_map = {}
    left = 0
    max_len = 0

    for right, ch in enumerate(s):
        if ch in char_map and char_map[ch] >= left:
            left = char_map[ch] + 1
        char_map[ch] = right
        max_len = max(max_len, right - left + 1)

    return max_len

print(length_of_longest_substring("abcabcbb")) # Output: 3
print(length_of_longest_substring("bbbbb"))    # Output: 1
```

C++ Implementation:
```cpp
#include <string>
#include <vector>
#include <algorithm>
#include <iostream>
using namespace std;

int lengthOfLongestSubstring(const string& s) {
    vector<int> lastIndex(256, -1);
    int left = 0, maxLen = 0;

    for (int right = 0; right < (int)s.length(); ++right) {
        unsigned char ch = s[right];
        if (lastIndex[ch] >= left) {
            left = lastIndex[ch] + 1;
        }
        lastIndex[ch] = right;
        maxLen = max(maxLen, right - left + 1);
    }
    return maxLen;
}
```
Time Complexity: O(N)
Auxiliary Space: O(min(N, Alphabet Size))

Optimal Solution (Boyer-Moore Voting Algorithm):

Key Concept:
If we pair up different elements, the majority element will still remain because it appears more than N / 2 times.

Python Implementation:
```python
def majority_element(nums: list[int]) -> int:
    candidate = None
    count = 0

    for num in nums:
        if count == 0:
            candidate = num
        count += (1 if num == candidate else -1)

    return candidate

print(majority_element([3, 2, 3]))             # Output: 3
print(majority_element([2, 2, 1, 1, 1, 2, 2])) # Output: 2
```

C++ Implementation:
```cpp
#include <vector>
#include <iostream>
using namespace std;

int majorityElement(const vector<int>& nums) {
    int candidate = 0, count = 0;
    for (int num : nums) {
        if (count == 0) {
            candidate = num;
        }
        count += (num == candidate) ? 1 : -1;
    }
    return candidate;
}
```
Time Complexity: O(N) single pass.
Auxiliary Space: O(1) strictly constant space.

Optimal Solution (Bottom-Up Dynamic Programming):

State Definition:
`dp[i]` = minimum number of coins needed to make amount `i`.
Base case: `dp[0] = 0`, all other `dp[i] = infinity`.
Transition: `dp[i] = min(dp[i], dp[i - coin] + 1)` for each coin in coins.

Python Implementation:
```python
def coin_change(coins: list[int], amount: int) -> int:
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] = min(dp[x], dp[x - coin] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

print(coin_change([1, 2, 5], 11)) # Output: 3
print(coin_change([2], 3))        # Output: -1
```

C++ Implementation:
```cpp
#include <vector>
#include <algorithm>
#include <iostream>
using namespace std;

int coinChange(const vector<int>& coins, int amount) {
    vector<int> dp(amount + 1, amount + 1);
    dp[0] = 0;

    for (int coin : coins) {
        for (int x = coin; x <= amount; ++x) {
            dp[x] = min(dp[x], dp[x - coin] + 1);
        }
    }
    return dp[amount] > amount ? -1 : dp[amount];
}
```
Time Complexity: O(amount * len(coins))
Auxiliary Space: O(amount)

Optimal Solution (3-Pointer Iterative Algorithm):

Approach:
- Use `prev = None`, `curr = head`.
- In each loop: save `next_node = curr.next`, set `curr.next = prev`, move `prev = curr`, `curr = next_node`.
- Return `prev` as new head.

Python Implementation:
```python
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def reverse_list(head: ListNode) -> ListNode:
    prev = None
    curr = head
    while curr:
        next_temp = curr.next
        curr.next = prev
        prev = curr
        curr = next_temp
    return prev
```

C++ Implementation:
```cpp
struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(nullptr) {}
};

ListNode* reverseList(ListNode* head) {
    ListNode *prev = nullptr, *curr = head;
    while (curr != nullptr) {
        ListNode* nextTemp = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nextTemp;
    }
    return prev;
}
```
Time Complexity: O(N)
Auxiliary Space: O(1) iterative

Optimal Stack Matching Solution:

Python Implementation:
```python
def is_valid_parentheses(s: str) -> bool:
    mapping = {')': '(', '}': '{', ']': '['}
    stack = []

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return len(stack) == 0

print(is_valid_parentheses("()[]{}")) # Output: True
print(is_valid_parentheses("(]"))     # Output: False
```

C++ Implementation:
```cpp
#include <string>
#include <stack>
#include <iostream>
using namespace std;

bool isValid(string s) {
    stack<char> st;
    for (char c : s) {
        if (c == '(' || c == '{' || c == '[') {
            st.push(c);
        } else {
            if (st.empty()) return false;
            char top = st.top();
            if ((c == ')' && top != '(') ||
                (c == '}' && top != '{') ||
                (c == ']' && top != '[')) {
                return false;
            }
            st.pop();
        }
    }
    return st.empty();
}
```
Time Complexity: O(N)
Auxiliary Space: O(N)
